import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%B5%E3%82%A4%E3%82%B3%E3%83%AD%E6%9C%AC.html","title":"サイコロ本","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.66,"words":197},"filePathRelative":"サイコロ本.md"}`),a={name:`サイコロ本.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="サイコロ本" tabindex="-1"><a class="header-anchor" href="#サイコロ本"><span>サイコロ本</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a>, <a href="./機械学習.html">機械学習</a></p><p><a href="https://amzn.to/4eD87Pt" target="_blank" rel="noopener noreferrer">amazon: Foundations of Statistical Natural Language Processing (English Edition)</a> の事。自然言語処理の定番教科書。</p><ul><li><a href="https://karino2.github.io/2018/12/27/165206.html" target="_blank" rel="noopener noreferrer">サイコロ本（Foundations of Statistical Natural Language Processing）を読む - なーんだ、ただの水たまりじゃないか</a></li><li><a href="./HMM.html">HMM</a>の記述が詳しい。</li></ul><h2 id="zipf-law-1-4-3" tabindex="-1"><a class="header-anchor" href="#zipf-law-1-4-3"><span>Zipf law (1.4.3)</span></a></h2><p>大規模なコーパスで単語（や単語種類）の出現頻度をカウントし、それを大きい順に並べると、 頻度fと順位rの間には、fと1/rが比例する、という関係がある。</p><p>つまり、<code>f*r = k</code>という定数kがある。</p><h3 id="含意" tabindex="-1"><a class="header-anchor" href="#含意"><span>含意</span></a></h3><p>コーパスは以下の３つを含むと解釈出来る</p><ul><li>少しの頻出語</li><li>中くらいの頻度の単語がそこそこある</li><li>低頻度の大量の単語</li></ul><p>低頻度の大量の単語、というのがこの法則と自然言語処理を考える上で重要になる性質。</p><h3 id="trigramのmleでのdata-sparseness-6-2-1" tabindex="-1"><a class="header-anchor" href="#trigramのmleでのdata-sparseness-6-2-1"><span>trigramのMLEでのdata sparseness (6.2.1)</span></a></h3><p>統計的な自然言語処理において、MLEでパラメータを推定しようとすると、多くの単語（やそれを処理した種類など）がsparseになる、という問題に直面する事になる。</p><p>n-gramのうちtrigram以降がsparseになるという問題。 IBMの特許データセットではトレーニングセットに現れない23%のトリグラムがテストセットで現れた、と報告している。</p><p>基本的にこうした低頻度のものをコーパスを増やして頻度を上げようとすると、さらなる低頻度のものが新しく追加されていって減っていかない、というのがZipf lawの含意でもある。</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};